<?php
$t=static fn(string $key): string=>esc(lang('Pharmacy.'.$key));
$money=static fn($value): string=>number_format((float)$value,2);
$quantity=static fn($value): string=>rtrim(rtrim(number_format((float)$value,3,'.',''),'0'),'.');
$due=max(0,round((float)$sale['net_total']-(float)$sale['paid_total'],2));
?>
<!doctype html><html lang="<?= esc(service('request')->getLocale(),'attr') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($sale['invoice_no']) ?> · <?= $t('receipt') ?></title>
