x dashed #cbd5e1;font-size:10px}.receipt-footer{text-align:center;border-top:1px dashed #cbd5e1;margin-top:20px;padding-top:17px;color:#64748b;font-size:10px}.receipt-footer p{margin:4px 0;white-space:pre-wrap}.receipt-footer small{font-size:9px;color:#94a3b8}.receipt-toolbar{display:flex;justify-content:center;margin:0 auto 16px;gap:8px}.receipt-toolbar button{border:0;background:#059669;color:white;padding:10px 18px;border-radius:8px;cursor:pointer;font-weight:600}.receipt-status{text-transform:capitalize}.receipt-due{font-weight:700;color:#b45309}
