<div class="receipt-toolbar"><button type="button" onclick="window.print()"><?= $t('printReceipt') ?></button></div>
<article class="receipt-paper" data-receipt-paper data-sale-id="<?= (int)$sale['id'] ?>" data-invoice="<?= esc($sale['invoice_no'],'attr') ?>">
    <header class="receipt-brand"><h1><?= esc($identity['store_name']) ?></h1><?php foreach (['address','phone','header'] as $field): if(trim($identity[$field])==='')continue; ?><p><?= esc($identity[$field]) ?></p><?php endforeach; ?></header>
    <div class="receipt-heading"><span><?= $t('salesReceipt') ?></span><strong><?= esc($sale['invoice_no']) ?></strong></div>
    <div class="receipt-meta"><div class="receipt-row"><span><?= $t('receiptDate') ?></span><span><?= esc($sale['sold_at']) ?></span></div><div class="receipt-row"><span><?= $t('cashier') ?></span><span><?= esc($sale['cashier_name']??'') ?></span></div><div class="receipt-row"><span><?= $t('customer') ?></span><span><?= esc($sale['customer_name']?:lang('Pharmacy.walkIn')) ?></span></div><div class="receipt-row"><span><?= $t('status') ?></span><span class="receipt-status"><?= esc($sale['status']) ?></span></div></div>
    <table class="receipt-items"><thead><tr><th><?= $t('medicines') ?></th><th><?= $t('lineTotal') ?></th></tr></thead><tbody><?php foreach ($sale['items'] as $item): ?><tr><td><strong><?= esc($item['description']) ?></strong><?php $facts=json_decode($item['pharmacy_medicine_snapshot']??'{}',true)??[]; if(!empty($facts['strength'])): ?><small><?= esc($facts['strength'].' ? '.($facts['dosage_form']??'')) ?></small><?php endif; ?><small><?= esc($quantity($item['quantity']).' '.$item['unit_label']) ?> × <?= $money($item['unit_price']) ?></small><?php if((float)$item['discount']>0): ?><small><?= $t('receiptDiscount') ?>: <?= $money($item['discount']) ?></small><?php endif; ?></td><td><?= $money($item['line_total']) ?></td></tr><?php endforeach; ?></tbody></table>
    <div class="receipt-totals"><div class="receipt-row"><span><?= $t('receiptSubtotal') ?></span><span><?= $money($sale['subtotal']) ?></span></div><?php if((float)$sale['discount']>0): ?><div class="receipt-row"><span><?= $t('receiptDiscount') ?></span><span>−<?= $money($sale['discount']) ?></span></div><?php endif; ?><div class="receipt-row"><span><?= $t('receiptTax') ?></span><span><?= $money($sale['tax_total']) ?></span></div><?php if((float)($sale['shipping']??0)>0): ?><div class="receipt-row"><span><?= $t('receiptShipping') ?></span><span><?= $money($sale['shipping']) ?></span></div><?php endif; ?>
    <div class="receipt-row receipt-total"><span><?= $t('receiptTotal') ?></span><strong><?= $money($sale['grand_total']) ?></strong></div>
    <?php if((float)$sale['returned_total']>0): ?><div class="receipt-row"><span><?= $t('receiptReturns') ?></span><span>−<?= $money($sale['returned_total']) ?></span></div><div class="receipt-row"><span><?= $t('receiptNet') ?></span><span><?= $money($sale['net_total']) ?></span></div><div class="receipt-row"><span><?= $t('receiptRefunded') ?></span><span><?= $money($sale['refunded_total']??0) ?></span></div><?php endif; ?>
    <div class="receipt-row"><span><?= $t('paid') ?></span><span><?= $money($sale['paid_total']) ?></span></div><div class="receipt-row <?= $due>0?'receipt-due':'' ?>"><span><?= $t('receiptBalance') ?></span><span><?= $money($due) ?></span></div></div>
    <?php if($sale['payments']): ?><div class="receipt-payments"><?php foreach($sale['payments'] as $payment): ?><div class="receipt-row"><span><?= esc(ucfirst($payment['method'])) ?></span><span><?= $money($payment['amount']) ?></span></div><?php endforeach; ?></div><?php endif; ?>
    <footer class="receipt-footer"><p><?= esc($identity['footer']) ?></p><small><?= esc($identity['system_name']) ?></small></footer>
</article></body></html>
